function prng(seed){var a=(seed>>>0)||1;return function(){a|=0;a=(a+0x6D2B79F5)|0;var t=Math.imul(a^(a>>>15),1|a);t=(t+Math.imul(t^(t>>>7),61|t))^t;return((t^(t>>>14))>>>0)/4294967296;};}
function demoRun(seed){var R=prng(seed*32452843+5);var fails=[];for(var i=0;i<9;i++){fails.push({up_h:200+((R()*1200)|0),down_min:5+((R()*55)|0)});}var upT=0,downT=0;fails.forEach(function(f){upT+=f.up_h;downT+=f.down_min/60;});var avail=upT/(upT+downT)*100;return{incidents:fails.length,mtbf_h:+(upT/fails.length).toFixed(1),mttr_min:+(downT/fails.length*60).toFixed(1),availability_pct:+avail.toFixed(3),sla_999_met:avail>=99.9};}
var SEED = 80001;
console.log(JSON.stringify(demoRun(SEED), null, 1));

